$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$component = Decode ""

$pagePath = Join-Path $root "app\provider\payments\page.tsx"
$componentPath = Join-Path $root "app\provider\payments\FinanceExportButton.tsx"
$reconciliationComponent = Join-Path $root "app\provider\payments\FinanceReconciliationStatus.tsx"
$financePath = Join-Path $root "app\api\provider\finance\route.ts"
$auditPath = Join-Path $root "app\api\provider\finance-audit\route.ts"

foreach ($path in @($pagePath, $reconciliationComponent, $financePath, $auditPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.14 : fichier requis introuvable : $path"
    }
}

$page = [System.IO.File]::ReadAllText($pagePath)
$reconciliation = [System.IO.File]::ReadAllText($reconciliationComponent)
$finance = [System.IO.File]::ReadAllText($financePath)
$audit = [System.IO.File]::ReadAllText($auditPath)

if (-not $page.Contains("KLYX_FINANCE_RECONCILIATION_PAGE_13_13")) {
    throw "13.14 : KLYX 13.13 page introuvable."
}

if (-not $reconciliation.Contains("KLYX_FINANCE_RECONCILIATION_UI_13_13")) {
    throw "13.14 : composant 13.13 introuvable."
}

if (-not $finance.Contains("KLYX_CANONICAL_FINANCE_TRANSACTIONS_13_11")) {
    throw "13.14 : transactions canoniques 13.11 introuvables."
}

if (-not $finance.Contains("KLYX_CANONICAL_FINANCE_RECONCILIATION_13_12")) {
    throw "13.14 : reconciliation 13.12 introuvable."
}

if (-not $audit.Contains("KLYX_GROUP_FINANCE_AUDIT_API_13_03")) {
    throw "13.14 : audit 13.03 introuvable."
}

if ($page.Contains("KLYX_CANONICAL_FINANCE_EXPORT_PAGE_13_14")) {
    Write-Host "KLYX 13.14 deja applique."
    exit 0
}

$renderNeedle = "<FinanceReconciliationStatus />"
$renderIndex = $page.IndexOf($renderNeedle)

if ($renderIndex -lt 0) {
    throw "13.14 : FinanceReconciliationStatus introuvable dans page.tsx."
}

$firstImportIndex = $page.IndexOf("import ")

if ($firstImportIndex -lt 0) {
    throw "13.14 : imports page.tsx introuvables."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $pagePath -Destination ($pagePath + ".bak-13-14-" + $timestamp) -Force

if (Test-Path -LiteralPath $componentPath) {
    Copy-Item -LiteralPath $componentPath -Destination ($componentPath + ".bak-13-14-" + $timestamp) -Force
}

$importLine = 'import FinanceExportButton from "./FinanceExportButton";' + "`r`n"

$page = $page.Insert($firstImportIndex, $importLine)

# Recalcule apres insertion import.
$renderIndex = $page.IndexOf($renderNeedle)

if ($renderIndex -lt 0) {
    throw "13.14 : rendu reconciliation perdu apres import."
}

$lineStart = $page.LastIndexOf("`n", $renderIndex)

if ($lineStart -lt 0) {
    $lineStart = 0
}
else {
    $lineStart += 1
}

$indentLength = 0

while ($lineStart + $indentLength -lt $page.Length -and $page[$lineStart + $indentLength] -eq " ") {
    $indentLength += 1
}

$indent = " " * $indentLength

$insertAt = $renderIndex + $renderNeedle.Length

$ui =
    "`r`n`r`n" +
    $indent + "{/* KLYX_CANONICAL_FINANCE_EXPORT_PAGE_13_14 */}" + "`r`n" +
    $indent + "<FinanceExportButton />"

$page = $page.Insert($insertAt, $ui)

[System.IO.File]::WriteAllText($componentPath, $component, $utf8)
[System.IO.File]::WriteAllText($pagePath, $page, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.14 APPLIQUE"
Write-Host "======================================"
Write-Host "Export financier : CSV"
Write-Host "Transactions : CANONIQUES"
Write-Host "Mission groupee : 1 TRANSACTION"
Write-Host "Reconciliation : INCLUSE"
Write-Host "Ledger brut : NON EXPORTE"
Write-Host "Export automatique : NON"
Write-Host "Stripe : INCHANGE"
Write-Host "Migration : AUCUNE"
Write-Host "======================================"
